-- Original design preserved for comparison; mixed SQL dialects, not deployable DDL.
CREATE TABLE "DISTRICT" (
  "DistrictID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "DistrictName" nvarchar(100) UNIQUE NOT NULL
);

CREATE TABLE "AGENCYTYPE" (
  "AgencyTypeID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "TypeName" nvarchar(100) UNIQUE NOT NULL,
  "MaxDebt" decimal(18,2) NOT NULL DEFAULT 0,
  "Status" varchar(20) NOT NULL
);

CREATE TABLE "AGENCY" (
  "AgencyID" varchar(20) PRIMARY KEY NOT NULL,
  "AgencyName" nvarchar(150) NOT NULL,
  "AgencyTypeID" int NOT NULL,
  "Phone" varchar(20),
  "Address" nvarchar(255),
  "DistrictID" int NOT NULL,
  "AcceptedDate" date NOT NULL,
  "Email" varchar(255) NOT NULL,
  "CurrentDebt" decimal(18,2) NOT NULL DEFAULT 0,
  "Status" varchar(20) NOT NULL
);

CREATE TABLE "UNIT" (
  "UnitID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "UnitName" nvarchar(100) UNIQUE NOT NULL,
  "Status" varchar(20) NOT NULL
);

CREATE TABLE "PRODUCT" (
  "ProductID" varchar(20) PRIMARY KEY NOT NULL,
  "ProductName" nvarchar(150) NOT NULL,
  "UnitID" int NOT NULL,
  "CurrentPurchasePrice" decimal(18,2) NOT NULL DEFAULT 0,
  "CurrentSellingPrice" decimal(18,2) NOT NULL DEFAULT 0,
  "CurrentStock" decimal(18,2) NOT NULL DEFAULT 0,
  "Status" varchar(20) NOT NULL
);

CREATE TABLE "STOCKRECEIPT" (
  "StockReceiptID" varchar(20) PRIMARY KEY NOT NULL,
  "ReceiptDate" date NOT NULL,
  "TotalAmount" decimal(18,2) NOT NULL DEFAULT 0,
  "Status" varchar(20) NOT NULL,
  "CancelReason" nvarchar(500)
);

CREATE TABLE "STOCKRECEIPTDETAIL" (
  "StockReceiptDetailID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "StockReceiptID" varchar(20) NOT NULL,
  "ProductID" varchar(20) NOT NULL,
  "Quantity" decimal(18,2) NOT NULL,
  "UnitPurchasePrice" decimal(18,2) NOT NULL,
  "LineAmount" decimal(18,2) NOT NULL
);

CREATE TABLE "STOCKISSUE" (
  "StockIssueID" varchar(20) PRIMARY KEY NOT NULL,
  "IssueDate" date NOT NULL,
  "AgencyID" varchar(20) NOT NULL,
  "TotalAmount" decimal(18,2) NOT NULL DEFAULT 0,
  "AmountPaid" decimal(18,2) NOT NULL DEFAULT 0,
  "RemainingAmount" decimal(18,2) NOT NULL DEFAULT 0,
  "Status" varchar(20) NOT NULL,
  "CancelReason" nvarchar(500)
);

CREATE TABLE "STOCKISSUEDETAIL" (
  "StockIssueDetailID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "StockIssueID" varchar(20) NOT NULL,
  "ProductID" varchar(20) NOT NULL,
  "Quantity" decimal(18,2) NOT NULL,
  "UnitSellingPrice" decimal(18,2) NOT NULL,
  "LineAmount" decimal(18,2) NOT NULL
);

CREATE TABLE "PAYMENTRECEIPT" (
  "PaymentReceiptID" varchar(20) PRIMARY KEY NOT NULL,
  "ReceiptDate" date NOT NULL,
  "AgencyID" varchar(20) NOT NULL,
  "Amount" decimal(18,2) NOT NULL,
  "PaymentMethod" varchar(30) NOT NULL,
  "ReceiptType" varchar(30) NOT NULL,
  "RelatedIssueID" varchar(20),
  "Status" varchar(20) NOT NULL,
  "CancelReason" nvarchar(500)
);

CREATE TABLE "PARAMETER" (
  "ParameterName" varchar(100) PRIMARY KEY NOT NULL,
  "Value" decimal(18,4) NOT NULL
);

CREATE TABLE "USERGROUP" (
  "UserGroupID" varchar(20) PRIMARY KEY NOT NULL,
  "GroupName" nvarchar(100) UNIQUE NOT NULL
);

CREATE TABLE "USERACCOUNT" (
  "UserID" varchar(20) PRIMARY KEY NOT NULL,
  "FullName" nvarchar(150) NOT NULL,
  "Email" varchar(255) UNIQUE NOT NULL,
  "PasswordHash" varchar(255) NOT NULL,
  "UserGroupID" varchar(20) NOT NULL,
  "Status" varchar(20) NOT NULL
);

CREATE TABLE "FUNCTION" (
  "FunctionID" varchar(20) PRIMARY KEY NOT NULL,
  "FunctionName" nvarchar(150) UNIQUE NOT NULL
);

CREATE TABLE "PERMISSION" (
  "PermissionID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "UserGroupID" varchar(20) NOT NULL,
  "FunctionID" varchar(20) NOT NULL,
  "IsAllowed" bit NOT NULL
);

CREATE TABLE "AUDITLOG" (
  "AuditLogID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "UserID" varchar(20) NOT NULL,
  "FunctionID" varchar(20) NOT NULL,
  "ActionTime" datetime2 NOT NULL,
  "ActionType" varchar(50) NOT NULL,
  "EntityName" varchar(100),
  "EntityID" varchar(50),
  "OldData" nvarchar(max),
  "NewData" nvarchar(max)
);

CREATE TABLE "ONLINEPAYMENT" (
  "TransactionID" varchar(50) PRIMARY KEY NOT NULL,
  "AgencyID" varchar(20) NOT NULL,
  "Amount" decimal(18,2) NOT NULL,
  "Status" varchar(20) NOT NULL,
  "PaymentTime" datetime2,
  "PaymentReceiptID" varchar(20) UNIQUE
);

CREATE UNIQUE INDEX ON "PERMISSION" ("UserGroupID", "FunctionID");

COMMENT ON COLUMN "AGENCYTYPE"."MaxDebt" IS '>= 0';

COMMENT ON COLUMN "AGENCYTYPE"."Status" IS 'ACTIVE / INACTIVE';

COMMENT ON COLUMN "AGENCY"."CurrentDebt" IS '>= 0; thuộc tính hiện trạng, tự động cập nhật';

COMMENT ON COLUMN "AGENCY"."Status" IS 'ACTIVE / TERMINATED';

COMMENT ON COLUMN "UNIT"."Status" IS 'ACTIVE / INACTIVE';

COMMENT ON COLUMN "PRODUCT"."CurrentPurchasePrice" IS '>= 0';

COMMENT ON COLUMN "PRODUCT"."CurrentSellingPrice" IS '= CurrentPurchasePrice * SellingPriceRate';

COMMENT ON COLUMN "PRODUCT"."CurrentStock" IS '>= 0; tồn kho hiện tại';

COMMENT ON COLUMN "PRODUCT"."Status" IS 'ACTIVE / INACTIVE';

COMMENT ON COLUMN "STOCKRECEIPT"."TotalAmount" IS '>= 0; tính từ chi tiết phiếu nhập';

COMMENT ON COLUMN "STOCKRECEIPT"."Status" IS 'ACTIVE / CANCELLED';

COMMENT ON COLUMN "STOCKRECEIPT"."CancelReason" IS 'Bắt buộc khi Status = CANCELLED';

COMMENT ON COLUMN "STOCKRECEIPTDETAIL"."Quantity" IS '> 0';

COMMENT ON COLUMN "STOCKRECEIPTDETAIL"."UnitPurchasePrice" IS '>= 0';

COMMENT ON COLUMN "STOCKRECEIPTDETAIL"."LineAmount" IS '= Quantity * UnitPurchasePrice';

COMMENT ON COLUMN "STOCKISSUE"."TotalAmount" IS '>= 0; tính từ chi tiết phiếu xuất';

COMMENT ON COLUMN "STOCKISSUE"."AmountPaid" IS '0 <= AmountPaid <= TotalAmount';

COMMENT ON COLUMN "STOCKISSUE"."RemainingAmount" IS '= TotalAmount - AmountPaid';

COMMENT ON COLUMN "STOCKISSUE"."Status" IS 'ACTIVE / CANCELLED';

COMMENT ON COLUMN "STOCKISSUE"."CancelReason" IS 'Bắt buộc khi Status = CANCELLED';

COMMENT ON COLUMN "STOCKISSUEDETAIL"."Quantity" IS '> 0 và không vượt tồn kho';

COMMENT ON COLUMN "STOCKISSUEDETAIL"."UnitSellingPrice" IS '>= 0; lưu giá tại thời điểm xuất';

COMMENT ON COLUMN "STOCKISSUEDETAIL"."LineAmount" IS '= Quantity * UnitSellingPrice';

COMMENT ON COLUMN "PAYMENTRECEIPT"."Amount" IS '> 0 và không vượt dư nợ';

COMMENT ON COLUMN "PAYMENTRECEIPT"."PaymentMethod" IS 'CASH / BANK_TRANSFER / ONLINE';

COMMENT ON COLUMN "PAYMENTRECEIPT"."ReceiptType" IS 'AUTO_FROM_ISSUE / DEBT_COLLECTION';

COMMENT ON COLUMN "PAYMENTRECEIPT"."RelatedIssueID" IS 'AUTO_FROM_ISSUE: bắt buộc; DEBT_COLLECTION: có thể NULL';

COMMENT ON COLUMN "PAYMENTRECEIPT"."Status" IS 'ACTIVE / CANCELLED';

COMMENT ON COLUMN "PAYMENTRECEIPT"."CancelReason" IS 'Bắt buộc khi Status = CANCELLED';

COMMENT ON TABLE "PARAMETER" IS 'Các giá trị ban đầu:
MaxAgenciesPerDistrict = 4
SellingPriceRate = 1.02
';

COMMENT ON COLUMN "USERACCOUNT"."Status" IS 'ACTIVE / LOCKED';

COMMENT ON COLUMN "PERMISSION"."IsAllowed" IS '1 = được phép; 0 = không được phép';

COMMENT ON COLUMN "AUDITLOG"."ActionType" IS 'UPDATE / CANCEL / RULE_CHANGE / PERMISSION_CHANGE / ...';

COMMENT ON COLUMN "ONLINEPAYMENT"."Amount" IS '> 0';

COMMENT ON COLUMN "ONLINEPAYMENT"."Status" IS 'PENDING / SUCCESS / FAILED / EXPIRED';

COMMENT ON COLUMN "ONLINEPAYMENT"."PaymentReceiptID" IS 'NULL trước khi SUCCESS';

ALTER TABLE "AGENCY" ADD FOREIGN KEY ("AgencyTypeID") REFERENCES "AGENCYTYPE" ("AgencyTypeID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "AGENCY" ADD FOREIGN KEY ("DistrictID") REFERENCES "DISTRICT" ("DistrictID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "PRODUCT" ADD FOREIGN KEY ("UnitID") REFERENCES "UNIT" ("UnitID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "STOCKRECEIPTDETAIL" ADD FOREIGN KEY ("StockReceiptID") REFERENCES "STOCKRECEIPT" ("StockReceiptID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "STOCKRECEIPTDETAIL" ADD FOREIGN KEY ("ProductID") REFERENCES "PRODUCT" ("ProductID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "STOCKISSUE" ADD FOREIGN KEY ("AgencyID") REFERENCES "AGENCY" ("AgencyID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "STOCKISSUEDETAIL" ADD FOREIGN KEY ("StockIssueID") REFERENCES "STOCKISSUE" ("StockIssueID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "STOCKISSUEDETAIL" ADD FOREIGN KEY ("ProductID") REFERENCES "PRODUCT" ("ProductID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "PAYMENTRECEIPT" ADD FOREIGN KEY ("AgencyID") REFERENCES "AGENCY" ("AgencyID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "PAYMENTRECEIPT" ADD FOREIGN KEY ("RelatedIssueID") REFERENCES "STOCKISSUE" ("StockIssueID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "USERACCOUNT" ADD FOREIGN KEY ("UserGroupID") REFERENCES "USERGROUP" ("UserGroupID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "PERMISSION" ADD FOREIGN KEY ("UserGroupID") REFERENCES "USERGROUP" ("UserGroupID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "PERMISSION" ADD FOREIGN KEY ("FunctionID") REFERENCES "FUNCTION" ("FunctionID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "AUDITLOG" ADD FOREIGN KEY ("UserID") REFERENCES "USERACCOUNT" ("UserID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "AUDITLOG" ADD FOREIGN KEY ("FunctionID") REFERENCES "FUNCTION" ("FunctionID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ONLINEPAYMENT" ADD FOREIGN KEY ("AgencyID") REFERENCES "AGENCY" ("AgencyID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ONLINEPAYMENT" ADD FOREIGN KEY ("PaymentReceiptID") REFERENCES "PAYMENTRECEIPT" ("PaymentReceiptID") DEFERRABLE INITIALLY IMMEDIATE;
